// console.log принимает ЛЮБОЕ значение и печатает его в консоль
console.log("Привет, мир!");   // печатает текст
console.log(42);                // печатает число
console.log(true);              // печатает логическое значение
console.log("Сумма:", 5 + 3);   // можно несколько аргументов через запятую

// Открой консоль браузера (F12) и нажми 'Запустить' — увидишь результат

